    [12000]={name="Limb Cleaver",quality=2,ilvl=55,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Hurley Blackbreath'. Pick it over the other reward choices. Starts with Ragnar Thunderbrew in Dun Morogh. Objective: Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.",zone="Blackrock Depths",questName="Hurley Blackbreath",lore="The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager. The villains! They don't deserve such a fine brew!, I have a tough task for you."},
    [12006]={name="Meadow Ring",quality=2,ilvl=22,reqLevel=17,sourceType="world_drop",instructions="World drop around level 17-24.",zone="The Barrens",zoneOpen=true},
    [12007]={name="Prairie Ring",quality=2,ilvl=25,reqLevel=20,sourceType="world_drop",instructions="World drop around level 20-26.",zone="The Barrens",zoneOpen=true},
    [12018]={name="Conservator Helm",quality=3,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12019]={name="Cerulean Talisman",quality=2,ilvl=32,reqLevel=27,sourceType="world_drop",instructions="World drop around level 26-33.",zone="Stranglethorn Vale"},
    [12020]={name="Thallium Choker",quality=2,ilvl=36,reqLevel=31,sourceType="world_drop",instructions="World drop around level 32-37.",zone="Stranglethorn Vale"},
    [12021]={name="Shieldplate Sabatons",quality=3,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12022]={name="Iridium Chain",quality=2,ilvl=41,reqLevel=36,sourceType="world_drop",instructions="World drop around level 36-42.",zone="Stranglethorn Vale"},
    [12026]={name="Quicksilver Pendant",quality=2,ilvl=59,reqLevel=54,sourceType="world_drop",instructions="World drop around level 38-61.",zone="Eastern Plaguelands"},
    [12038]={name="Lagrave's Seal",quality=2,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'The Last Element'.",zone="Blackrock Depths",questName="The Last Element",lore="There is work to be had for those venturing into the depths. The Dark Irons have mastered creation of extremely powerful golems."},
    [12040]={name="Forest Pendant",quality=2,ilvl=38,reqLevel=33,sourceType="world_drop",instructions="World drop around level 33-39.",zone="Stranglethorn Vale"},
    [12047]={name="Spectral Necklace",quality=2,ilvl=30,reqLevel=25,sourceType="world_drop",instructions="World drop around level 25-31.",zone="Stranglethorn Vale"},
    [12049]={name="Splintsteel Armor",quality=2,ilvl=53,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Ribbly Screwspigot'. Pick it over the other reward choices. Starts with Yuka Screwspigot in Burning Steppes. Objective: Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.",zone="Blackrock Depths",questName="Ribbly Screwspigot",lore="My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another."},
    [12052]={name="Ring of the Moon",quality=2,ilvl=21,reqLevel=16,sourceType="world_drop",instructions="World drop around level 16-22.",zone="The Barrens",zoneOpen=true},
